// ===== 有声书源 B · 音乐/全量链路  v4.6 =====
// 来源：接口实测调优（2026-11-11）。
//
// 【引擎契约 v3】对齐 HarmonyOS-book 开源引擎契约（源码核实）：
//  1) 脚本阶段不写 fields/list：Runner.scripted() 按 BOOK_FIELD_NAMES 同名键取值。
//     ★ 封面是 coverUrl，不是 cover → 写 cover 会「不出封面」。
//  2) 顶层 type=audio + 每条记录 type:"audio" + content.audio 规则
//     → content() 判定 kind='audio'，播放器才启动（否则音频直链被当文字渲染）。
//  3) 发现页 menu.url 渲染进 __url → 脚本 ctx.url（Runner.explore():704,727）。
//
// 【分类修复】接口实测（含分类参数）：
//   kuwo-albums?classifyId={id}&pn={page}&rn={size}&categoryId={cat}&sortType=tsScore
//   旧版只传 classifyId → 实测返回全站 total=35003（点「玄幻奇幻」出全站热门）= 分类不对。
//   榜单 kuwo-rank-data 返回字段是 list，不是 books；tabId/tagId 来自 kuwo-rank-tabs。
//   分类树来自 kuwo-classify：sections[].categoryId + sections[].child[].classifyId。
//
// 【播放修复】取链链路：
//   play_api.url（api.php 动态下发，当前 http://43.142.122.173/）
//   + /kuwo.php?type={音质}&rid={rid} → data.add（实测 200 audio/mpeg 真实直链）。
//   兜底：官方 anti.s?type=convert_url&rid={rid}（实测直接返回真实 MP3 直链）。
//   云端 kuwo-play 的 url 恒为空（只给歌词），不作为取链来源。
//  约束：QuickJS；所有阶段/按钮只引用本文件里的函数名；状态走 vars.get/set。

var SUPA = "https://backend.appmiaoda.com/projects/supabase345057433544081408/functions/v1";
var ANON = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJhdWQiOiJhdXRoZW50aWNhdGVkIiwiZXhwIjoyMTAxNjk1MzAzLCJpc3MiOiJzdXBhYmFzZSIsInJvbGUiOiJhbm9uIiwic3ViIjoiYW5vbiJ9.d_zv-NO7ifqZtHZHdEFYo0Kaxldn9NeW7Yy4YmHnsnc";
var KW_BASE = "https://mobilebasedata.kuwo.cn/basedata.s";
var KW_RANK = "https://search.kuwo.cn/r.s";
var KW_POLICY = "https://tsm.kuwo.cn/audioApi/a.p";
var KW_ANTI = "https://antiserver.kuwo.cn/anti.s";
var KW_CONFIG = "http://www.tingshu8.top/api.php";
var PLAY_API_FALLBACK = "http://43.142.122.173";

var HOST_POOL = [SUPA];
var PROBE_PATH = "/kuwo-rank-tabs";

function hostOf() {
  var raw = String(vars.get("server") || "").trim();
  var want = "";
  if (raw && !/^自动/.test(raw)) {
    var sp = raw.indexOf(" ");
    want = (sp > 0 ? raw.substring(sp + 1) : raw).replace(/\/+$/, "");  // 「云端 URL」→ 取地址
  }
  if (want) return want;
  var ms = String(vars.get("server_ms") || "");
  if (ms) {
    var parts = ms.split(","), best = "", bestMs = 1e9;
    for (var i = 0; i < parts.length; i++) {
      var kv = parts[i].split(":");
      if (kv.length === 2 && parseInt(kv[1], 10) > 0 && parseInt(kv[1], 10) < bestMs) {
        bestMs = parseInt(kv[1], 10); best = kv[0];
      }
    }
    if (best && HOST_POOL.indexOf(best) >= 0) return best;
  }
  return HOST_POOL[0];
}
function markHost(host, ok, ms) {
  if (!ok) return;
  var map = {}, s = String(vars.get("server_ms") || ""), parts = s ? s.split(",") : [];
  for (var i = 0; i < parts.length; i++) {
    var kv = parts[i].split(":");
    if (kv.length === 2) map[kv[0]] = parseInt(kv[1], 10) || 0;
  }
  map[host] = ms;
  var out = [];
  for (var k in map) if (map.hasOwnProperty(k)) out.push(k + ":" + map[k]);
  vars.set("server_ms", out.join(","));
}

function reqHeaders(url) {
  var u = String(url);
  if (u.indexOf("appmiaoda.com") >= 0) {
    return { "apikey": ANON, "Authorization": "Bearer " + ANON,
             "Accept": "application/json", "User-Agent": "tingyue/1.1.8" };
  }
  if (u.indexOf("43.142.122.173") >= 0 || u.indexOf("115.190.207.125") >= 0) {
    return { "User-Agent": "Mozilla/5.0 (Linux; Android 13; Mobile) AppleWebKit/537.36 Chrome/120.0.0.0 Mobile Safari/537.36",
             "Accept": "*/*" };
  }
  return { "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
           "Referer": "https://kuwo.cn/", "Accept": "*/*" };
}

// 云端限流体识别（appmiaoda 免费规格：429 状态或 200+ConcurrencyLimit 文案）
function isLimitedBody(s) {
  return String(s || "").indexOf("ConcurrencyLimit") >= 0 || String(s || "").indexOf("并发请求上限") >= 0;
}

var _apiCache = {};
function apiGet(url, desc) {
  // 请求级短缓存：同 url 90 秒内复用，避免发现页/详情/目录重试风暴叠加云端并发限流
  var hit = _apiCache[url];
  if (hit && (Date.now() - hit.t) < 90000 && hit.s) return hit.s;
  var r = null, last = "";
  for (var i = 0; i < 4; i++) {
    var t0 = Date.now();
    try { r = http.get(url, { headers: reqHeaders(url) }); }
    catch (e) { r = { ok: false, status: 0, error: String(e && e.message || e) }; }
    var body = String((r && r.body) || "");
    if (r && r.ok && r.status === 200 && !isLimitedBody(body)) {
      if (url.indexOf("appmiaoda.com") >= 0) {
        try { markHost(hostOf(), true, Date.now() - t0); } catch (e0) {}
      }
      _apiCache[url] = { t: Date.now(), s: body };
      return body;
    }
    if (isLimitedBody(body)) { last = "HTTP 200 云端限流"; }
    else last = r && r.status ? "HTTP " + r.status : "网络错误";
    // 429/5xx 退避重试（appmiaoda 免费规格并发窗口极短，瞬发重试必撞限流）
    if (!(r && (r.status === 429 || r.status >= 500))) break;
    try { sleep(600 * (i + 1) + 500); } catch (e2) {}
  }
  var limited = String(r && r.body || "").indexOf("ConcurrencyLimit") >= 0 || (r && r.status === 429);
  var hint = limited
    ? "\n云端聚合并发已满（429），稍等几秒重试；或到「书源设置」点『🔎 连通性自检』看是哪一段不通。"
    : "\n请到「书源设置」点『🔎 连通性自检』，它会逐段测出是哪一步失败。";
  throw new Error((desc || "请求") + "失败：" + last + hint);
}
function jsonGet(url, desc) {
  var s = apiGet(url, desc);
  try { return JSON.parse(s); } catch (e) { return null; }
}
function looseJson(s) {
  try { return JSON.parse(s); } catch (e) {}
  try {
    var t = String(s).replace(/\r?\n/g, " ");
    t = t.replace(/([{,]\s*)'([^']+)'\s*:/g, '$1"$2":').replace(/':/g, '":').replace(/'/g, '"');
    return JSON.parse(t);
  } catch (e2) { return null; }
}
function dec(s) {
  return String(s == null ? "" : s)
    .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">").replace(/&#39;/g, "'").replace(/&quot;/g, '"')
    .replace(/<[^>]+>/g, "").trim();
}
function https(s) { return String(s || "").replace(/^http:\/\//, "https://"); }
function idOf(s) {
  var t = String(s || "");
  var m = t.match(/[?&](?:id|albumId|albumid)=(\d+)/) || t.match(/(\d{6,})/);
  return m ? m[1] : "";
}
function ctxUrl(ctx) {
  var c = ctx || {};
  // ★ 章节地址优先于书籍地址：引擎 content 阶段 ctx.url 恒为空字符串，
  //   章节地址在 ctx.chapter.url、书籍地址在 ctx.book.bookUrl（源码 scriptContext）。
  //   若 book 分支在前，content 阶段会取到书籍 URL → 匹配失败 → 静默返回空 audio
  //   → 真机报「正文规则没有返回音频地址」。
  return String(c.url || c.bookUrl || c.tocUrl || c.chapterUrl || c.link ||
                (c.chapter && (c.chapter.url || c.chapter.chapterUrl)) ||
                (c.book && (c.book.url || c.book.bookUrl || c.book.tocUrl)) ||
                (c.item && c.item.url) || "");
}
function bookUrlOf(id) { return KW_BASE + "?type=get_album_info&id=" + id; }

// 书记录工厂：引擎标准键名 + type=audio
// 封面高清化（2026-11-13 实测）：酷我 albumcover 各尺寸档通用，300/400 → 500
function hdPic(url) {
  var s = https(url);
  if (!s) return s;
  return s.replace(/(\/star\/albumcover\/)\d+\//, "$1500/");
}
function bookRec(title, id, author, cover, intro) {
  return {
    name: dec(title),
    bookUrl: bookUrlOf(id),
    author: dec(author) || "未知",
    coverUrl: hdPic(cover),
    intro: dec(intro),
    type: "audio"
  };
}
// play_api host：优先 api.php 动态下发，失败用内置兜底；结果缓存进 vars
function playHost() {
  var cached = String(vars.get("play_host") || "");
  if (cached) return cached;
  var host = PLAY_API_FALLBACK;
  try {
    var d = jsonGet(KW_CONFIG, "取播放服务");
    var u = d && d.data && d.data.play_api && d.data.play_api.url;
    if (u && /^https?:\/\//i.test(String(u))) host = String(u).replace(/\/+$/, "");
  } catch (e) {}
  vars.set("play_host", host);
  return host;
}
function antiUrl(rid) {
  return KW_ANTI + "?type=convert_url&rid=" + encodeURIComponent(rid) +
         "&format=mp3&response=url";
}
function playUrl(rid) {
  var q = String(vars.get("quality") || "128");
  if (!/^\d+$/.test(q)) q = "128";
  return playHost() + "/kuwo.php?type=" + q + "&rid=" + encodeURIComponent(rid);
}

// ---------- 设置页动作 ----------

function actResetServer() {
  vars.set("server", HOST_POOL[0]);
  vars.set("server_ms", "");
  vars.set("play_host", "");
  try { ui.refreshExplore(); } catch (e) {}
  return "♻️ 已复位到默认云端后端，耗时记录与播放服务缓存已清空。";
}
function probePool(pool) {
  var out = [];
  for (var i = 0; i < pool.length; i++) {
    var t = Date.now(), ok = false;
    try {
      var r = http.get(pool[i] + PROBE_PATH, { headers: reqHeaders(pool[i]) });
      ok = !!(r && r.ok && r.status === 200);
    } catch (e) {}
    out.push({ host: pool[i], ok: ok, ms: Date.now() - t });
  }
  return out;
}
// ===== 三按钮：诊断 / 重测速并应用 / 恢复默认 =====
// 诊断：先给结论再给明细；当前音频线路失效时自动切到可用线路；兜底线路不通不计为故障。
function actDiagnose() {
  var out = [], lines = [], i, fails = 0, fixed = [], best = null;
  var steps = [
    ["搜索", hostOf() + "/kuwo-search?keyword=%E5%91%A8%E6%9D%B0%E4%BC%A6&pn=0&rn=20", 1],
    ["首页", hostOf() + "/kuwo-books", 1],
    ["榜单", hostOf() + "/kuwo-rank-data?tabId=13&tagId=27&pn=1&rn=20", 1],
    ["分类标签", hostOf() + "/kuwo-channel-tabs?categoryId=37", 1],
    ["分类列表", hostOf() + "/kuwo-albums?classifyId=254&pn=1&rn=20&categoryId=37&sortType=tsScore", 1],
    ["详情", bookUrlOf("95648538"), 1],
    ["目录", hostOf() + "/kuwo-episodes?albumId=95648538", 1],
    ["取链", hostOf() + "/kuwo-play?rid=605531597&quality=128&host=" + encodeURIComponent(playHost()), 1],
    ["取链兜底(anti.s)", antiUrl("605531597"), 0],
    ["取链兜底(kuwo.php)", playUrl("605531597"), 0]
  ];
  for (i = 0; i < steps.length; i++) {
    try {
      var t = Date.now(), s = apiGet(steps[i][1], steps[i][0]);
      out.push("  ✅ " + steps[i][0] + "  " + s.length + " 字节 / " + (Date.now() - t) + "ms");
    } catch (e) {
      if (steps[i][2]) fails++;
      out.push("  " + (steps[i][2] ? "❌" : "○") + " " + steps[i][0] + "  " + String(e.message || e).split("\n")[0]);
    }
  }
  var scored = [];
  for (i = 0; i < LINE_HOSTS.length; i++) {
    var t2 = Date.now(), ok = false;
    try { var r = http.get(lineProbeUrl(LINE_HOSTS[i].key), { timeout: 8000 }); ok = !!(r && r.ok && r.status === 200); } catch (e2) {}
    var ms = Date.now() - t2;
    scored.push({ k: LINE_HOSTS[i].key, n: LINE_HOSTS[i].n, ok: ok, ms: ms });
    lines.push("  " + (ok ? "✅" : "❌") + " " + LINE_HOSTS[i].n + "  " + (ok ? ms + "ms" : "不通"));
    if (ok && (!best || ms < best.ms)) best = { k: LINE_HOSTS[i].key, n: LINE_HOSTS[i].n, ms: ms };
  }
  var curLine = String(vars.get("line") || ""), auto = /^自动/.test(curLine) || !curLine, curOk = auto;
  for (i = 0; i < scored.length; i++) if (scored[i].n === curLine) curOk = scored[i].ok;
  if (!curOk && best) {
    vars.set("line", best.n);
    vars.set("line_ms", scored.map(function (x) { return x.k + ":" + (x.ok ? x.ms : 999999); }).join(","));
    fixed.push("音频线路 " + curLine + " 不通 → 已切到 " + best.n);
  }
  if (fixed.length) { try { ui.refreshExplore(); } catch (e3) {} }

  var head;
  if (!fails && !fixed.length) head = "🩺 诊断结果：✅ 关键链路正常（搜索 / 首页 / 榜单 / 分类 / 详情 / 目录 / 取链 全通）";
  else if (fixed.length) head = "🩺 诊断结果：⚠️ 必需环节失败 " + fails + " 处，已自动修复 " + fixed.length + " 处";
  else head = "🩺 诊断结果：❌ 必需环节失败 " + fails + " 处，需人工处理";
  var res = [head, "  当前 云端后端 " + hostOf() + " · 播放服务 " + playHost() + " · 音频线路 " + (auto ? "自动" : curOk ? curLine : best ? best.n : "无可用")];
  for (i = 0; i < fixed.length; i++) res.push("  🔧 " + fixed[i]);
  res.push("", "链路明细");
  res = res.concat(out);
  res.push("", "音频线路");
  res = res.concat(lines);
  res.push("提示：标 ○ 的是取链兜底线路，不通不影响使用（云端 kuwo-play 可用即可播放）。");
  return res.join("\n");
}
function serverOptions(ctx) {
  var ms = String(vars.get("server_ms") || ""), scored = [];
  for (var i = 0; i < HOST_POOL.length; i++) {
    var v = 1e9, parts = ms ? ms.split(",") : [];
    for (var j = 0; j < parts.length; j++) {
      var kv = parts[j].split(":");
      if (kv.length === 2 && kv[0] === HOST_POOL[i]) v = parseInt(kv[1], 10) || 1e9;
    }
    scored.push({ h: HOST_POOL[i], v: v });
  }
  scored.sort(function (a, b) { return a.v - b.v; });
  var out = [];
  for (var k = 0; k < scored.length; k++) out.push(scored[k].h);
  return out;
}

// ---------- 音频线路测速（v4.6）：anti.s / kuwo.php 直连，按真实取链耗时排序 ----------
var LINE_AUTO = "自动（优先上次成功线路）";
var LINE_CLOUD = "线路① 云端 kuwo-play";
var LINE_PROBE_RID = "605531597";
function lineProbeUrl(k) { return k === "anti" ? antiUrl(LINE_PROBE_RID) : playUrl(LINE_PROBE_RID); }
var LINE_HOSTS = [
  { key: "anti", n: "线路② 官方 anti.s" },
  { key: "php", n: "线路③ kuwo.php 直连" }
];
function lineOptions(ctx) {
  var ms = String(vars.get("line_ms") || ""), parts = ms ? ms.split(",") : [];
  function score(n) {
    for (var j = 0; j < parts.length; j++) { var kv = parts[j].split(":"); if (kv.length === 2 && kv[0] === n) return parseInt(kv[1], 10) || 1e9; }
    return 1e9;
  }
  var items = [];
  for (var i = 0; i < LINE_HOSTS.length; i++) items.push({ n: LINE_HOSTS[i].n, v: score(LINE_HOSTS[i].key) });
  items.sort(function (a, b) { return a.v - b.v; });
  var out = [LINE_AUTO, LINE_CLOUD];
  for (var k = 0; k < items.length; k++) out.push(items[k].n);
  return out;
}
// 重测速：一次测完云端后端与音频线路并应用最优（「并应用」写进标签，避免误以为是只读操作）。
function actRetest() {
  if (typeof ui !== "undefined" && ui && ui.toast) ui.toast("正在重测速…");
  var res = probePool(HOST_POOL), out = ["⚡ 重测速完成，已应用最快线路"], i, okH = 0;
  for (i = 0; i < res.length; i++) if (res[i].ok) okH++;
  out.push("  云端后端 " + okH + "/" + res.length + " 可用");
  var scored = [], best = null;
  for (i = 0; i < LINE_HOSTS.length; i++) {
    var t = Date.now(), ok = false;
    try { var r = http.get(lineProbeUrl(LINE_HOSTS[i].key), { timeout: 8000 }); ok = !!(r && r.ok && r.status === 200); } catch (e) {}
    var ms = Date.now() - t;
    scored.push({ k: LINE_HOSTS[i].key, n: LINE_HOSTS[i].n, ok: ok, ms: ms });
    if (ok && (!best || ms < best.ms)) best = { k: LINE_HOSTS[i].key, n: LINE_HOSTS[i].n, ms: ms };
  }
  vars.set("line_ms", scored.map(function (x) { return x.k + ":" + (x.ok ? x.ms : 999999); }).join(","));
  if (best) vars.set("line", best.n);
  try { ui.refreshExplore(); } catch (e2) {}
  out.push("  音频线路 " + (best ? best.n + "  " + best.ms + "ms" : "全不通，保持原设置"));
  out.push("", "提示：日常无需手动执行；取链失败或切网后跑一次即可。");
  return out.join("\n");
}

// ---------- 五阶段：真实业务解析，返回值一律引擎标准键名 ----------
function stageSearch(ctx) {
  var key = String((ctx && (ctx.key || ctx.keyword)) || "").trim();
  if (!key) return [];
  var page = parseInt(String((ctx && ctx.page) || 1), 10) || 1;
  var out = [];
  try {
    var d = jsonGet(hostOf() + "/kuwo-search?keyword=" + encodeURIComponent(key) +
                    "&pn=" + ((page - 1) * 20) + "&rn=20", "搜索");
    var bs = (d && d.books) || [];
    for (var i = 0; i < bs.length; i++) {
      var id = String(bs[i].id || "");
      if (!id) continue;
      out.push(bookRec(bs[i].title, id, bs[i].author || bs[i].narrator,
                       bs[i].cover, bs[i].description));
    }
  } catch (e) {}
  return out;
}

// 发现：menu.url 编码三种意图
//   home                         → kuwo-books（返回 books）
//   rank:{tabId}:{tagId}         → kuwo-rank-data（返回 list）
//   cate:{classifyId}:{catId}    → kuwo-albums（补全 pn/rn/categoryId/sortType）
// ★ 音乐分类用 37 号频道「热歌神曲」：标签由 kuwo-channel-tabs?categoryId=37 下发，
//   catId 必须是 37；用 2 会落到有声小说分类（玄幻/都市），这就是旧版「分类不对」的原因。
function stageExplore(ctx) {
  var u = ctxUrl(ctx), out = [];
  var page = parseInt(String((ctx && ctx.page) || 1), 10) || 1;
  var path = "/kuwo-books";
  var dataKey = "books";
  var m = u.match(/^rank:(\d+):(\d+)/);
  var c = u.match(/^cate:(\d+):(\d+)/);
  if (m) {
    path = "/kuwo-rank-data?tabId=" + m[1] + "&tagId=" + m[2] + "&pn=" + page + "&rn=30";
    dataKey = "list";
  } else if (c) {
    path = "/kuwo-albums?classifyId=" + c[1] + "&pn=" + page + "&rn=30" +
           "&categoryId=" + c[2] + "&sortType=tsScore";
  } else if (u.indexOf("cate:") >= 0) {
    var only = u.split(":")[1];
    path = "/kuwo-albums?classifyId=" + only + "&pn=" + page + "&rn=30&categoryId=2&sortType=tsScore";
  }
  try {
    var d = jsonGet(hostOf() + path, "发现");
    var bs = (d && (d[dataKey] || d.books || d.list || (d.data && d.data.books))) || [];
    for (var i = 0; i < bs.length; i++) {
      var it = bs[i], id = String(it.id || it.albumId || "");
      if (!id) continue;
      out.push(bookRec(it.title || it.name, id, it.author || it.narrator || it.artist,
                       it.cover || it.pic || it.img, it.description || it.subtitle || it.intro));
    }
  } catch (e) {}
  if (!out.length) {
    throw new Error("发现页取数失败（" + path + "）：多为云端聚合并发限流，稍等几秒下拉刷新即可；" +
                    "若持续失败请点『🔎 连通性自检』查看哪一段不通。");
  }
  return out;
}

// 详情：官方 basedata.s（字段全）；云端 kuwo-albuminfo 的 meta 兜底
function stageDetail(ctx) {
  var id = idOf(ctxUrl(ctx));
  if (!id) return {};
  var r = { name: "", author: "", coverUrl: "", intro: "", tocUrl: bookUrlOf(id), type: "audio" };
  try {
    var d = jsonGet(bookUrlOf(id), "详情");
    if (d && (d.name || d.albumid)) {
      r.name = dec(d.name || d.book_name); r.author = dec(d.artist) || "未知";
      r.coverUrl = hdPic(d.big_pic || d.pic); r.intro = dec(d.desc || d.info);
    }
  } catch (e) {}
  if (!r.name) {
    try {
      var c = jsonGet(hostOf() + "/kuwo-albuminfo?albumId=" + encodeURIComponent(id), "云端详情");
      var m = c && c.meta;
      if (m) { r.name = dec(m.name); r.author = dec(m.author); r.coverUrl = hdPic(m.cover); r.intro = dec(m.description); }
    } catch (e2) {}
  }
  return r;
}

// 目录：云端 kuwo-episodes；官方 policy.songList / r.s.musiclist 双兜底
// chapter.url = kuwo://{rid}（自定义协议，content 阶段再取真实直链）
function stageToc(ctx) {
  var id = idOf(ctxUrl(ctx));
  if (!id) return [];
  var out = [], seen = {};
  function push(rid, title) {
    rid = String(rid || "");
    if (!rid || seen[rid]) return;
    seen[rid] = 1;
    out.push({ title: dec(title) || "第 " + (out.length + 1) + " 集", url: "kuwo://" + rid });
  }
  try {
    var d = jsonGet(hostOf() + "/kuwo-episodes?albumId=" + encodeURIComponent(id), "云端目录");
    var cs = (d && d.chapters) || [];
    for (var i = 0; i < cs.length; i++) push(cs[i].id, cs[i].title);
  } catch (e) {}
  if (!out.length) {
    try {
      var p = jsonGet(KW_POLICY + "?op=policy&albumids=" + encodeURIComponent(id) + "&uid=0", "官方目录");
      var sl = (p && p.albums && p.albums[0] && p.albums[0].songList) || [];
      for (var j = 0; j < sl.length; j++) push(sl[j].id, sl[j].name);
    } catch (e2) {}
  }
  if (!out.length) {
    try {
      var s = apiGet(KW_RANK + "?stype=albuminfo&albumid=" + encodeURIComponent(id) + "&pn=0&rn=100", "官方专辑目录");
      var o = looseJson(s), ml = (o && o.musiclist) || [];
      for (var k = 0; k < ml.length; k++) push(ml[k].id, ml[k].name);
    } catch (e3) {}
  }
  return out;
}

// 正文：从 kuwo://{rid} 取真实直链（v4.5：新增「音频线路」设置项，手动选线优先）
// 线路：① 云端 kuwo-play（必须带 host=play_api.url，否则 url 恒空）
//       ② 官方 anti.s（返回干净 https 直链）
//       ③ play_api 的 kuwo.php（data.add）
// 自动模式 = 上次成功线路优先（记忆 kw_last_line）；手动指定 = 所选线路排最前，
// 失败仍按顺序兜底其余线路，保证总能播。
function stageContent(ctx) {
  var u = ctxUrl(ctx);
  if (!u) return { audio: "" };
  var m = u.match(/kuwo:\/\/(\d+)/) || u.match(/[?&]rid=(\d+)/);
  if (!m) return { audio: "" };
  var rid = m[1];
  var q = String(vars.get("quality") || "128");
  if (!/^\d+$/.test(q)) q = "128";

  var mode = String(vars.get("line") || "自动（优先上次成功线路）");
  var last = String(vars.get("kw_last_line") || "");
  // order: 0=云端 kuwo-play  1=anti.s  2=kuwo.php
  var order = [0, 1, 2];
  function bringToFront(k) { order = [k].concat(order.filter(function (x) { return x !== k; })); }
  if (mode.indexOf("云端") >= 0 && mode.indexOf("①") >= 0) bringToFront(0);
  else if (mode.indexOf("anti.s") >= 0) bringToFront(1);
  else if (mode.indexOf("kuwo.php") >= 0) bringToFront(2);
  else if (last !== "") { var li = parseInt(last, 10); if (li >= 0 && li <= 2) bringToFront(li); }

  var errors = [];
  for (var oi = 0; oi < order.length; oi++) {
    var which = order[oi];
    var v = "";
    try {
      if (which === 0) {
        var d0 = jsonGet(hostOf() + "/kuwo-play?rid=" + encodeURIComponent(rid) +
                         "&quality=" + q + "&host=" + encodeURIComponent(playHost()), "云端取链");
        v = String((d0 && d0.url) || (d0 && d0.data && d0.data.url) || "");
      } else if (which === 1) {
        v = String(apiGet(antiUrl(rid), "取播放地址兜底")).trim();
      } else {
        var d = jsonGet(playUrl(rid), "取播放地址");
        v = String((d && d.add) || "");
      }
    } catch (e1) { errors.push(["云端kuwo-play", "anti.s", "kuwo.php"][which] + ": " + String(e1.message || e1).split("\n")[0]); }
    if (/^https?:\/\//i.test(v)) {
      try { vars.set("kw_last_line", String(which)); } catch (e2) {}
      return { audio: https(v), text: https(v) };
    }
  }
  throw new Error("未取到音频地址：云端 kuwo-play / 官方 anti.s / play_api kuwo.php 三条取链均未返回直链。" +
                  "请点『🔎 连通性自检』看是哪一段失败（该曲目可能需 VIP 或已下架）。");
}
